    splashrunes(g, m, x, y, r, a, t, sd) { ell(g, x, y, r, r * FL, m.c[3], a * 0.45); for (let i = 0; i < 3; i++) { const k = (t + i / 3) % 1; ringE(g, x, y, r * k, 0.06, m.c[7], a * (1 - k)); } runesAlong(g, m, x - r, y, x + r, y, a, t, sd); const R = rng(sd); for (let i = 0; i < 8; i++) { const an = R() * TAU; circ(g, x + Math.cos(an) * r * 0.8, y + Math.sin(an) * r * 0.8 * FL - R() * 0.4, 0.06, '#ffffff', a); } },
    clawmarks(g, m, x, y, r, a, t, sd) { ell(g, x, y, r, r * FL, m.c[1], a * 0.25); const R = rng(sd); for (let i = 0; i < 3; i++) { const an = R() * TAU, l = r * 0.8; const cx = x + (R() - 0.5) * r * 0.6, cy = y + (R() - 0.5) * r * 0.6 * FL; LINE.claws(g, m, cx - Math.cos(an) * l / 2, cy - Math.sin(an) * l / 2 * FL, cx + Math.cos(an) * l / 2, cy + Math.sin(an) * l / 2 * FL, 0.6, a, t, i); } scatter(g, m, x, y, r * 0.7, a * 0.7, t, sd + 5, 3, 0.2); },
    starfield(g, m, x, y, r, a, t, sd) { ell(g, x, y, r, r * FL, '#0a1030', a * 0.6); const R = rng(sd), P = []; for (let i = 0; i < 9; i++) { const an = R() * TAU, d = Math.sqrt(R()) * r; P.push([x + Math.cos(an) * d, y + Math.sin(an) * d * FL]); } A(g, a * 0.6); g.strokeStyle = m.c[5]; g.lineWidth = 0.03; g.beginPath(); P.forEach(([px, py], i) => (i ? g.lineTo(px, py) : g.moveTo(px, py))); g.stroke(); P.forEach(([px, py], i) => { g.save(); g.translate(px, py); glowOn(g, m.c[7], 8); sparkle(g, 0.12 + (i % 3) * 0.06, m.c[7], a * (0.6 + 0.4 * Math.sin(t * 7 + i))); glowOff(g); g.restore(); }); },
    featherfall(g, m, x, y, r, a, t, sd) { glowOn(g, m.c[6], 12); ell(g, x, y, r, r * FL, m.c[6], a * 0.25); glowOff(g); const R = rng(sd); for (let i = 0; i < 9; i++) { const an = R() * TAU, d = Math.sqrt(R()) * r, ph = (t * 0.5 + R()) % 1; g.save(); g.translate(x + Math.cos(an) * d + Math.sin(t * 3 + i) * 0.2, y + Math.sin(an) * d * FL - 1.4 * (1 - ph)); GL.feather(g, 0.18, m.c, t + i); g.restore(); } },
    souls(g, m, x, y, r, a, t, sd) { ell(g, x, y, r, r * FL, m.c[0], a * 0.55); ringE(g, x, y, r, 0.05, m.c[5], a); const R = rng(sd); for (let i = 0; i < 6; i++) { const an = R() * TAU, d = Math.sqrt(R()) * r, ph = (t * 0.7 + R()) % 1; g.save(); g.translate(x + Math.cos(an) * d, y + Math.sin(an) * d * FL - ph * 1.2); A(g, a * (1 - ph)); GL.wisp(g, 0.2, m.c, t + i); g.restore(); } },
    confetti(g, m, x, y, r, a, t, sd) { const cols = ['#ff4a7a', '#ffd24a', '#4affb0', '#4ab0ff', '#d04aff', '#ffffff']; const R = rng(sd); for (let i = 0; i < 28; i++) { const an = R() * TAU, d = Math.sqrt(R()) * r, fall = ((t * 0.7 + R()) % 1); g.save(); g.translate(x + Math.cos(an) * d, y + Math.sin(an) * d * FL - (1 - fall) * 1.2); g.rotate(t * 6 + i); poly(g, [[-0.06, -0.03], [0.06, -0.03], [0.06, 0.03], [-0.06, 0.03]], cols[i % 6], a); g.restore(); } g.save(); g.translate(x, y - 0.6); GL.firework(g, r * 0.3 * (0.6 + 0.4 * Math.sin(t * 4)), m.c, t); g.restore(); },
    mirrorshards(g, m, x, y, r, a, t, sd) { const R = rng(sd); for (let i = 0; i < 10; i++) { const an = R() * TAU, d = Math.sqrt(R()) * r, px = x + Math.cos(an) * d, py = y + Math.sin(an) * d * FL - 0.2, s = 0.15 + R() * 0.2; g.save(); g.translate(px, py); g.rotate(t * 2 + i); poly(g, [[0, -s], [s * 0.6, 0], [0, s * 0.8], [-s * 0.5, 0.1]], i % 2 ? '#c8ffe8' : m.c[6], a * 0.85); poly(g, [[0, -s], [s * 0.6, 0], [0, s * 0.8], [-s * 0.5, 0.1]], '#ffffff', a, 0.02); g.restore(); } ringE(g, x, y, r, 0.05, m.c[5], a * 0.7); },
    darkpool(g, m, x, y, r, a, t, sd) { ell(g, x, y, r, r * FL, m.c[0], a * 0.85); ell(g, x, y, r * 0.8, r * 0.8 * FL, m.c[1], a * 0.6); const R = rng(sd); for (let i = 0; i < 4; i++) { const an = R() * TAU, d = Math.sqrt(R()) * r * 0.7; g.save(); g.translate(x + Math.cos(an) * d, y + Math.sin(an) * d * FL); GL.eye(g, 0.16, m.c, t + i); g.restore(); } for (let i = 0; i < 5; i++) { const an = i / 5 * TAU + t; LINE.tendril(g, m, x + Math.cos(an) * r * 0.9, y + Math.sin(an) * r * 0.9 * FL, x + Math.cos(an) * r * 0.9, y + Math.sin(an) * r * 0.9 * FL - 0.9, 0.25, a * 0.8, t, i); } },
    sandpool(g, m, x, y, r, a, t, sd) { AREA.dial(g, m, x, y, r, a, t, sd); }
